import {esc} from './organiser-utils.js';
const check=async q=>{const r=await q;if(r.error)throw r.error;return r.data;};
const types={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','application/pdf':'pdf'};
const titleOf=p=>p.memo||p.title||'Additional supporting document';
export const fileField='<label>Supporting image or PDF (up to 8 MB)<input name="proof" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></label>';
export async function submitReview(sb,kind,payload,file){
 const i=crypto.randomUUID();let f='';
 if(file?.size){if(!types[file.type]||file.size>8388608)throw Error('Choose a JPG, PNG, WebP or PDF up to 8 MB.');const {data:{user},error}=await sb.auth.getUser();if(error||!user)throw Error('Sign in again to upload evidence.');f=user.id+'/'+i+'/proof.'+types[file.type];await check(sb.storage.from('elan-oc-review-files').upload(f,file,{upsert:false,contentType:file.type}));}
 await check(sb.rpc('elan_review_submit',{i,k:kind,p:payload,f}));return i;
}
export async function proof(sb,path){const blob=await check(sb.storage.from('elan-oc-review-files').download(path)),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=path.split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200);}
const seats={director:'Director',assistant:'Assistant Director'},verdict={approve:'Approve now',later:'Keep for later',reject:'Reject'};
export async function reviewView(box,sb,seat,scope='pending',offset=0){
 const rows=await check(sb.from('elan_oc_requests').select('*,elan_oc_votes(seat,decision,note,round,actor)').eq('status',scope).order('created_at',{ascending:false}).order('id').range(offset,offset+24));
 box.innerHTML='<p>Both the Director and Assistant Director review each submission. A deferred item needs two fresh decisions when reopened.</p><label>Show <select data-filter>'+['pending','approved','later','rejected'].map(x=>'<option '+(x===scope?'selected':'')+'>'+x+'</option>').join('')+'</select></label><div data-items></div><p role="status"></p>';
 const refresh=(s=scope,o=offset)=>reviewView(box,sb,seat,s,o).catch(e=>box.querySelector('[role=status]').textContent=e.message);
 box.querySelector('select').onchange=e=>refresh(e.target.value,0);
 for(const r of rows){const p=r.payload,votes=r.elan_oc_votes||[],current=votes.filter(v=>v.round===r.round),a=document.createElement('article');a.className='team-card';const fields={journal:['book_date','kind','amount','method','reverses'],board:['audience','kind','body','url'],record:['target','reference'],attachment:['entry']}[r.kind]||[];const dl=Object.entries({...Object.fromEntries(fields.filter(k=>p[k]).map(k=>[k,p[k]])),...Object.fromEntries(Object.entries(p.details||{}).map(([k,v])=>[(p.labels||{})[k]||k,v]))}).map(([k,v])=>'<p><strong>'+esc(k.replaceAll('_',' '))+':</strong> '+esc(v)+'</p>').join('');
 a.innerHTML='<small>'+esc(r.department+' · '+r.kind+' · '+r.status)+'</small><h3>'+esc(titleOf(p))+'</h3>'+dl+(r.proof?'<button data-proof>Download supporting evidence</button>':'')+'<ul>'+Object.entries(seats).map(([k,l])=>{const v=current.find(v=>v.seat===k);return '<li>'+l+': '+(v?esc(verdict[v.decision])+(v.note?' · '+esc(v.note):''):'Awaiting decision')+'</li>';}).join('')+'</ul>'+(votes.some(v=>v.round<r.round)?'<details><summary>Earlier decisions</summary>'+votes.filter(v=>v.round<r.round).map(v=>'<p>Round '+v.round+' · '+seats[v.seat]+' · '+esc(verdict[v.decision])+' '+esc(v.note)+'</p>').join('')+'</details>':'')+(seat&&scope==='pending'&&!current.some(v=>v.seat===seat)?'<form class="team-form"><label>Your decision<select name="decision" required><option value="">Choose a decision</option>'+Object.entries(verdict).map(([v,l])=>'<option value="'+v+'">'+l+'</option>').join('')+'</select></label><label>Review note<textarea name="note" maxlength="1500"></textarea></label><button>Record decision</button></form>':'')+(seat&&scope==='later'?'<button data-reopen>Request a fresh review</button>':'')+'<p role="status"></p>';box.querySelector('[data-items]').append(a);const msg=a.querySelector('[role=status]');
 const b=a.querySelector('[data-proof]');if(b)b.onclick=()=>proof(sb,r.proof).catch(e=>msg.textContent=e.message);
 const f=a.querySelector('form');if(f)f.onsubmit=async e=>{e.preventDefault();if(f.inert)return;f.inert=true;try{const d=f.decision.value;if(!confirm('Record “'+verdict[d]+'” as '+seats[seat]+'?'))return;await check(sb.rpc('elan_review_decide',{i:r.id,d,n:f.note.value.trim()}));await refresh();}catch(err){msg.textContent=err.message;}finally{f.inert=false;}};
 const reopen=a.querySelector('[data-reopen]');if(reopen)reopen.onclick=async()=>{try{await check(sb.rpc('elan_review_reopen',{i:r.id}));await refresh('pending',0);}catch(e){msg.textContent=e.message;}};}
 if(!rows.length)box.querySelector('[data-items]').textContent='No '+scope+' submissions here.';
 for(const [label,idx] of [['Previous',offset-25],['Next',offset+25]]){if(idx<0||idx>offset&&rows.length<25)continue;const b=document.createElement('button');b.textContent=label;b.onclick=()=>refresh(scope,idx);box.append(b);}
}
export async function configureReviewers(host,sb){const rows=await check(sb.from('elan_oc_reviewers').select('seat,label'));const section=document.createElement('section');section.className='oc-panel';section.innerHTML='<h3>Leadership approval seats</h3><p>Choose two distinct verified accounts. Both are required before any department submission can be applied.</p>'+Object.entries(seats).map(([s,l])=>'<form data-seat="'+s+'"><label>'+l+' email<input type="email" required value="'+esc(rows.find(r=>r.seat===s)?.label||'')+'"></label><button>Assign '+l+'</button> <button type="button" data-clear>Remove seat</button><p role="status"></p></form>').join('');host.append(section);for(const f of section.querySelectorAll('form')){const save=async val=>{if(!confirm('Change the '+seats[f.dataset.seat]+' approval seat?'))return;f.inert=true;try{await check(sb.rpc('elan_review_seat',{s:f.dataset.seat,email_in:val}));f.querySelector('input').value=val;f.querySelector('[role=status]').textContent=val?'Assigned.':'Removed.';}catch(e){f.querySelector('[role=status]').textContent=e.message;}finally{f.inert=false;}};f.onsubmit=e=>{e.preventDefault();save(f.querySelector('input').value.trim());};f.querySelector('[data-clear]').onclick=()=>save('');}}
